47: export function resolveStoragePolicy(configured: string | undefined | null): StoragePolicy {
48:   if (configured === undefined || configured === null || configured.trim() === "") {
49:     return { mode: MEMORY, reason: "unset-defaults-to-memory", misconfigured: false };
50:   }
51: 
52:   const normalised = configured.trim().toLowerCase();
53:   if (normalised === PERSISTENT) {
54:     return { mode: PERSISTENT, reason: "explicit-persistent", misconfigured: false };
55:   }
56:   if (normalised === MEMORY) {
57:     return { mode: MEMORY, reason: "explicit-memory", misconfigured: false };
58:   }
59: 
60:   // Deliberately not a throw: refusing to start is a worse failure than running
61:   // safely and reporting it. But it is flagged, because a deployment that
62:   // intended persistence and mistyped the value must not silently run
63:   // ephemeral and appear to work.
64:   return { mode: MEMORY, reason: "unrecognised-defaults-to-memory", misconfigured: true };
65: }
